+// resolveConfigJSONPath returns the path to Antigravity's config.json.
+func resolveConfigJSONPath() (string, error) {
+	if configDir := os.Getenv("ANTIGRAVITY_CONFIG_DIR"); configDir != "" {
+		return filepath.Join(configDir, "config.json"), nil
+	}
+	home, err := os.UserHomeDir()
+	if err != nil {
+		return "", fmt.Errorf("resolving home directory: %w", err)
+	}
+	return filepath.Join(home, ".gemini", "config", "config.json"), nil
+}
+
+// ensurePluginEnabled sets plugins.repo-memory.enabled=true in Antigravity's
+// config.json. This is necessary because:
+// - Plugins with sidecars that had agent_permissions defaulted to disabled
+// - The disabled state persists in config.json across reinstalls
+// - config.json takes precedence over the plugin directory
+func ensurePluginEnabled() error {
+	configPath, err := resolveConfigJSONPath()
+	if err != nil {
+		return err
+	}
+
+	// Read existing config (or start fresh)
+	var config map[string]interface{}
+	data, err := os.ReadFile(configPath)
+	if err != nil {
+		if os.IsNotExist(err) {
+			config = make(map[string]interface{})
+		} else {
+			return fmt.Errorf("reading %s: %w", configPath, err)
+		}
+	} else {
+		if err := json.Unmarshal(data, &config); err != nil {
+			return fmt.Errorf("parsing %s: %w", configPath, err)
+		}
+	}
+
+	// Get or create plugins map
+	pluginsRaw, ok := config["plugins"]
+	if !ok {
+		pluginsRaw = make(map[string]interface{})
+		config["plugins"] = pluginsRaw
+	}
+	plugins, ok := pluginsRaw.(map[string]interface{})
+	if !ok {
+		return fmt.Errorf("unexpected plugins type in %s", configPath)
+	}
+
+	// Check current state — skip write if already enabled
+	if rmRaw, ok := plugins["repo-memory"]; ok {
+		if rm, ok := rmRaw.(map[string]interface{}); ok {
+			if enabled, ok := rm["enabled"].(bool); ok && enabled {
+				return nil // already enabled
+			}
+		}
+	}
+
+	// Set enabled
+	rmConfig, ok := plugins["repo-memory"].(map[string]interface{})
+	if !ok {
+		rmConfig = make(map[string]interface{})
+	}
+	rmConfig["enabled"] = true
+	plugins["repo-memory"] = rmConfig
+
+	// Write back with indentation to match existing format
+	out, err := json.MarshalIndent(config, "", "    ")
+	if err != nil {
+		return fmt.Errorf("marshalling config: %w", err)
+	}
+	out = append(out, '\n')
+
+	if err := os.WriteFile(configPath, out, 0644); err != nil {
+		return fmt.Errorf("writing %s: %w", configPath, err)
+	}
+
+	return nil
+}
+
